package com.petcare.enterprise.clinical.presentation;

import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.authentication;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.header;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

import com.petcare.enterprise.identity.infrastructure.security.PetCarePrincipal;
import com.petcare.enterprise.test.PostgreSqlIntegrationTest;
import java.util.List;
import java.util.UUID;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.test.web.servlet.MockMvc;

@SpringBootTest @AutoConfigureMockMvc
class PatientControllerIntegrationTest extends PostgreSqlIntegrationTest {
 @Autowired MockMvc mvc; @Autowired JdbcTemplate jdbc;
 @Test void createsPatientMedicalRecordAndAuditWithinTenant() throws Exception { Fixture f=fixture("patient-a"); UUID owner=owner(f,true); mvc.perform(post("/api/v1/patients").with(authentication(auth(f,"PATIENT_CREATE"))).contentType(MediaType.APPLICATION_JSON).content(body(owner))).andExpect(status().isCreated()).andExpect(header().string("Location",org.hamcrest.Matchers.containsString("/api/v1/patients/"))).andExpect(jsonPath("$.ownerId").value(owner.toString())).andExpect(jsonPath("$.name").value("Luna")); assertCount("patients",f.tenant,1); assertCount("medical_records",f.tenant,1); assertCount("audit_entries",f.tenant,1); }
 @Test void rejectsUnauthenticatedUnauthorizedAndForeignOrInactiveOwners() throws Exception { Fixture a=fixture("patient-owner-a"), b=fixture("patient-owner-b"); UUID inactive=owner(a,false), foreign=owner(b,true); mvc.perform(post("/api/v1/patients").contentType(MediaType.APPLICATION_JSON).content(body(inactive))).andExpect(status().isUnauthorized()); mvc.perform(post("/api/v1/patients").with(authentication(auth(a,"OWNER_CREATE"))).contentType(MediaType.APPLICATION_JSON).content(body(inactive))).andExpect(status().isForbidden()); mvc.perform(post("/api/v1/patients").with(authentication(auth(a,"PATIENT_CREATE"))).contentType(MediaType.APPLICATION_JSON).content(body(inactive))).andExpect(status().isNotFound()); mvc.perform(post("/api/v1/patients").with(authentication(auth(a,"PATIENT_CREATE"))).contentType(MediaType.APPLICATION_JSON).content(body(foreign))).andExpect(status().isNotFound()); }
 @Test void validatesRequiredAndFutureBirthDate() throws Exception { Fixture f=fixture("patient-validation"); UUID owner=owner(f,true); mvc.perform(post("/api/v1/patients").with(authentication(auth(f,"PATIENT_CREATE"))).contentType(MediaType.APPLICATION_JSON).content("{\"ownerId\":\""+owner+"\",\"name\":\"\",\"species\":\"PERRO\",\"sex\":\"HEMBRA\"}")).andExpect(status().isBadRequest()); mvc.perform(post("/api/v1/patients").with(authentication(auth(f,"PATIENT_CREATE"))).contentType(MediaType.APPLICATION_JSON).content("{\"ownerId\":\""+owner+"\",\"name\":\"Luna\",\"species\":\"PERRO\",\"sex\":\"HEMBRA\",\"birthDate\":\"2999-01-01\"}")).andExpect(status().isBadRequest()); }
 @Test void rollsBackPatientWhenMedicalRecordOrAuditFails() throws Exception { Fixture f=fixture("patient-atomic"); UUID owner=owner(f,true); jdbc.execute("CREATE OR REPLACE FUNCTION reject_patient_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'history failure'; END; $$"); jdbc.execute("CREATE TRIGGER reject_patient_history_trigger BEFORE INSERT ON medical_records FOR EACH ROW EXECUTE FUNCTION reject_patient_history()"); mvc.perform(post("/api/v1/patients").with(authentication(auth(f,"PATIENT_CREATE"))).contentType(MediaType.APPLICATION_JSON).content(body(owner))).andExpect(status().isInternalServerError()); assertCount("patients",f.tenant,0); jdbc.execute("DROP TRIGGER reject_patient_history_trigger ON medical_records"); jdbc.execute("DROP FUNCTION reject_patient_history()"); mvc.perform(post("/api/v1/patients").with(authentication(auth(new Fixture(f.tenant,UUID.randomUUID(),f.user),"PATIENT_CREATE"))).contentType(MediaType.APPLICATION_JSON).content(body(owner))).andExpect(status().isConflict()); assertCount("patients",f.tenant,0); }
 @Test void scopesMicrochipUniquenessToTenantAndAllowsNulls() throws Exception { Fixture a=fixture("patient-chip-a"),b=fixture("patient-chip-b"); UUID ownerA=owner(a,true),ownerB=owner(b,true); mvc.perform(post("/api/v1/patients").with(authentication(auth(a,"PATIENT_CREATE"))).contentType(MediaType.APPLICATION_JSON).content(body(ownerA))).andExpect(status().isCreated()); mvc.perform(post("/api/v1/patients").with(authentication(auth(a,"PATIENT_CREATE"))).contentType(MediaType.APPLICATION_JSON).content(body(ownerA))).andExpect(status().isConflict()); mvc.perform(post("/api/v1/patients").with(authentication(auth(b,"PATIENT_CREATE"))).contentType(MediaType.APPLICATION_JSON).content(body(ownerB))).andExpect(status().isCreated()); String withoutChip="{\"ownerId\":\""+ownerA+"\",\"name\":\"Sin chip\",\"species\":\"GATO\",\"sex\":\"MACHO\"}"; mvc.perform(post("/api/v1/patients").with(authentication(auth(a,"PATIENT_CREATE"))).contentType(MediaType.APPLICATION_JSON).content(withoutChip)).andExpect(status().isCreated()); mvc.perform(post("/api/v1/patients").with(authentication(auth(a,"PATIENT_CREATE"))).contentType(MediaType.APPLICATION_JSON).content(withoutChip.replace("Sin chip","Sin chip dos"))).andExpect(status().isCreated()); }
 @Test void persistsOnlySafeAuditMetadata() throws Exception { Fixture f=fixture("patient-audit"); UUID owner=owner(f,true); mvc.perform(post("/api/v1/patients").with(authentication(auth(f,"PATIENT_CREATE"))).contentType(MediaType.APPLICATION_JSON).content(body(owner))).andExpect(status().isCreated()); var audit=jdbc.queryForMap("SELECT tenant_id,actor_user_id,correlation_id,new_data::text FROM audit_entries WHERE tenant_id=? AND action='PATIENT_CREATED'",f.tenant); org.assertj.core.api.Assertions.assertThat(audit.get("tenant_id")).isEqualTo(f.tenant); org.assertj.core.api.Assertions.assertThat(audit.get("actor_user_id")).isEqualTo(f.user); org.assertj.core.api.Assertions.assertThat(audit.get("correlation_id")).isNotNull(); org.assertj.core.api.Assertions.assertThat(String.valueOf(audit.get("new_data"))).contains("name","species","sex").doesNotContain("microchip","birthDate","sterilized"); }
 private Fixture fixture(String slug){ UUID t=UUID.randomUUID(),br=UUID.randomUUID(),u=UUID.randomUUID(); jdbc.update("INSERT INTO tenants(id,name,slug,plan,status,created_at) VALUES(?,?,?,'STARTER','ACTIVO',now())",t,"Fictional clinic",slug+UUID.randomUUID().toString().substring(0,6)); jdbc.update("INSERT INTO branches(id,tenant_id,name,time_zone,active,created_at) VALUES(?,?,?,'America/Lima',true,now())",br,t,"Main"); return new Fixture(t,br,u); }
 private UUID owner(Fixture f,boolean active){ UUID id=UUID.randomUUID(); jdbc.update("INSERT INTO owners(id,tenant_id,first_name,last_name,phone,active) VALUES(?,?, 'Owner','Fictional','999123456',?)",id,f.tenant,active); return id; }
 private UsernamePasswordAuthenticationToken auth(Fixture f,String... p){ var a=List.of(p).stream().map(SimpleGrantedAuthority::new).toList(); return UsernamePasswordAuthenticationToken.authenticated(new PetCarePrincipal(f.user,f.tenant,f.branch,a),null,a); }
 private String body(UUID owner){ return "{\"ownerId\":\""+owner+"\",\"name\":\" Luna \",\"species\":\" Perro \",\"breed\":\" Mestizo \",\"sex\":\"hembra\",\"microchip\":\" chip-1 \",\"sterilized\":true}"; }
 private void assertCount(String table,UUID tenant,int expected){ Integer count=jdbc.queryForObject("SELECT count(*) FROM "+table+" WHERE tenant_id=?",Integer.class,tenant); org.assertj.core.api.Assertions.assertThat(count).isEqualTo(expected); }
 private record Fixture(UUID tenant,UUID branch,UUID user){}
}
